import{z as E,x as A,o as i,c as p,q as t,j as s,D as o,d as e,s as d,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"并查集","description":"","frontmatter":{"title":"并查集","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/union-find.md","filePath":"cs/union-find.md","lastUpdated":1791413859000}'),B={name:"cs/union-find.md"};function c(f,a,u,m,D,h){const r=A("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="并查集" tabindex="-1">并查集 <a class="header-anchor" href="#并查集" aria-label="Permalink to &quot;并查集&quot;">​</a></h1><div class="epigraph"><p>元素分在若干不相交集合里，只问是否同类、以及把两类合并；路径压缩加按秩合并以后，摊还几乎是常数。</p><footer>—— 据 Tarjan, Efficiency of a Good But Not Linear Set Union Algorithm, JACM 1975；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/radix-tree">上一课</a>按键的符号结构存放。<a href="/cs/adt-cost">抽象数据类型</a>允许合同里没有「按值查找」。<a href="/cs/amortized-analysis">摊还分析</a>已经准备好势能语言。<a href="/cs/graph-definition">图的定义</a>里连通分量是分区。本课不重讲前缀。缺口是分区 ADT：<code>find</code> 与 <code>union</code>，表示用父指针森林，分析用摊还，不是期望散列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>维护 \\(\\{1,\\ldots,n\\}\\) 的划分。查询 \\(a,b\\) 是否同一块，或把两块合成一块。用 BST 集合存每块，union 要搬元素。缺口是：<strong>每元素一个父指针，根为代表；union 只改根；find 沿父走到根</strong>。朴素则树可变链，\\(\\Theta(n)\\)。按秩（或按大小）合并限制高度；路径压缩把沿途点直接挂到根。</p><p>Tarjan 证明压缩+按秩的摊还是反 Ackermann \\(\\alpha(n)\\)，实际等于常数。本课不把 \\(\\alpha\\) 的定义展开成数论，只钉「比 \\(\\log\\) 还扁的摊还」。</p><p><span class="marginnote">并查集不给出块内元素列表（除非另存）。合同极窄，所以才能极快。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>MakeSet(x)</code>：父为自己，秩 0。<code>Find(x)</code>：递归或两趟压缩。<code>Union(x,y)</code>：比两根的秩，矮挂高，相等则升一方之秩。</p>',9)),(i(),s(l,null,{default:o(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%85%83%E7%B4%A0%22%5D%20--%3E%20P%5B%22%E7%88%B6%E6%8C%87%E9%92%88%22%5D%0A%20%20P%20--%3E%20ROOT%5B%22%E6%A0%B9%20%3D%20%E4%BB%A3%E8%A1%A8%22%5D%0A%20%20ROOT%20--%3E%20U%5B%22union%20%E5%8F%AA%E9%93%BE%E6%8E%A5%E6%A0%B9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"与链表表示的「按大小合并」同类：总是把小块挂到大块，无压缩时高度 \\(O(\\log n)\\)。压缩再把已经走过的路摊掉。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,[e("一次 "),n("code",null,"Union(x,y)"),e(" 的决策路径如下：先各自找根，再比秩，矮的挂到高的下面。")],-1)),(i(),s(l,null,{default:o(()=>[d(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22Union(x%2C%20y)%22%5D%20--%3E%20F1%5B%22Find(x)%20%E6%89%BE%E5%88%B0%E6%A0%B9%20rx%22%5D%0A%20%20S%20--%3E%20F2%5B%22Find(y)%20%E6%89%BE%E5%88%B0%E6%A0%B9%20ry%22%5D%0A%20%20F1%20--%3E%20C%7B%22rx%20%3D%3D%20ry%20%3F%22%7D%0A%20%20F2%20--%3E%20C%0A%20%20C%20--%3E%7C%E7%9B%B8%E5%90%8C%7C%20DONE%5B%22%E5%B7%B2%E5%9C%A8%E5%90%8C%E5%9D%97%2C%20%E4%BB%80%E4%B9%88%E9%83%BD%E4%B8%8D%E5%81%9A%22%5D%0A%20%20C%20--%3E%7C%E4%B8%8D%E5%90%8C%7C%20R%7B%22%E7%A7%A9%20rx%20%5Clt%20%E7%A7%A9%20ry%20%3F%22%7D%0A%20%20R%20--%3E%7C%E6%98%AF%7C%20A1%5B%22parent%5Brx%5D%20%3D%20ry%22%5D%0A%20%20R%20--%3E%7C%E5%90%A6%7C%20A2%5B%22parent%5Bry%5D%20%3D%20rx%22%5D%0A%20%20A1%20--%3E%20EQ%7B%22%E4%B8%A4%E6%A0%B9%E7%A7%A9%E7%9B%B8%E7%AD%89%3F%22%7D%0A%20%20A2%20--%3E%20EQ%0A%20%20EQ%20--%3E%7C%E6%98%AF%7C%20INC%5B%22%E7%A7%A9%E5%A4%A7%E7%9A%84%E4%B8%80%E6%96%B9%E5%8A%A0%201%22%5D%0A%20%20INC%20--%3E%20END2%5B%22%E5%90%88%E5%B9%B6%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>Kruskal 最小生成树把边按权加入、用并查集检测是否成环——算法课再用，本课只交结构。动态连通性若还要删边，并查集不够，合同不含 split。</p><p><span class="marginnote">注意「已在同块」这条短路分支：不先比根就合并，会把两个集合悄悄连成环的雏形。Kruskal 判环正是靠这个返回值——根相同说明加这条边会成环，直接跳过。</span></p><p><code>find</code> 的返回值只作代表，代表编号可以随 union 改变，调用方不得缓存过期根。</p><p><span class="marginnote">路径压缩可以想象成「走一次就修一次路」：你沿 \\(3\\to 2\\to 1\\) 的链找到根 1，回头顺手把 3 和 2 都直接挂到 1 上。下次任何人从 3 出发，一步就到根——走过的路越多人走越平。</span></p><p><span class="marginnote">常见误区：把 <code>find</code> 返回的代表编号存进字典长期复用。两次 union 之后代表可能换人，缓存就指向过期根。要么每次现查，要么约定读前先 find 一次。</span></p><p>表示是数组 <code>parent[i]</code>，局部性好于树节点堆分配。秩数组并行。这是<a href="/cs/array-random-access">数组与随机访问</a>作为内部表示，对外仍是分区 ADT。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入可持久化并查集、不处理并查集上的删除。也不把 \\(\\alpha(n)\\) 写成 \\(O(1)\\) 最坏——最坏单次仍可较长，摊还小。</p><p>后课默认：不相交集合查询用并查集。图要存边而不只是分量时，需要邻接表示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分区 ADT：find / union；森林 + 压缩 + 按秩，摊还几乎常数。</li><li>不支持列成员、不支持删边。</li><li>图的边集怎么放，下一课邻接表与矩阵。</li><li>代表编号可随 union 改变；调用方不得缓存过期根。</li><li>出处：Tarjan, <em>JACM</em>, 1975；Cormen et al. 第 21 章。</li></ul>',11))])}const x=E(B,[["render",c]]);export{T as __pageData,x as default};
